You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\begin{theorem}
    \label{thm:3sat}
    There is a polynomial-time randomized algorithm that, given a satisfiable 3SAT formula with $n$ variables, finds with high probability an assignment satisfying a $(\frac 78 + \wt{\Omega}(n^{-\frac 34}))$-fraction of the clauses.
\end{theorem}

\subsection{Sum-of-Squares SDPs} 
\label{sec:sos-prelims}

A \emph{degree-$\ell$ pseudo-distribution} $\mu$ over variables $x_1, x_2, \ldots, x_n$ corresponds to a linear operator $\pE_{\mu}$ that maps polynomials of degree $\leq \ell$ to real numbers and satisfies $\pE_\mu\, 1=1$ and $\pE_{\mu}[p^2] \geq 0$ for every polynomial $p(x_1,x_2, \ldots, x_n)$ of degree $\leq \ell/2$. We say that such a pseudo-distribution satisfies the \emph{hypercube} constraints if $\pE_{\mu}[p x_i^2] = \pE_{\mu}[p]$ for every polynomial $p$ of degree $\leq \ell-2$ and every $i\in [n]$. We say that such a pseudo-distribution satisfies the \emph{unit sphere} constraints if $\pE_{\mu}[ \norm{x}_2^2 p] =  \pE_{\mu}[p]$ for every $p$ of degree $\leq \ell-2$. 

\paragraph{Reweighting.} Given a pseudo-distribution $\mu$ over the unit sphere or the hypercube, a \emph{reweighting} of $\mu$ by a sum-of-squares polynomial $q$ satisfying $\pE_{\mu}[q]>0$ is a pseudo-distribution $\mu'$ that maps any polynomial $p$ to $\pE_{\mu'}[p] = \pE_{\mu}[pq]/\pE_{\mu}[q]$. For any $\mu$ of degree $\ell$ and $q$ of degree $ r < \ell$, $\mu'$ is a pseudo-distribution of degree at least $\ell-r$. Furthermore, if $\mu$ satisfies the unit sphere (or the hypercube) constraints then so does $\mu'$ as long as $r\leq \ell- 2$.

\begin{theorem}[Charikar-Wirth rounding \cite{CW04}]
    \label{thm:charikar-wirth}
    Given any degree-2 pseudo-distribution $\mu$ over $x\in\{\pm 1\}^n$, for any $T > 0$, there is a polynomial-time sampleable distribution $\mathcal D$ supported on $\{\pm 1\}^n$ such that for any matrix $M\in \R^{n\times n}$ with zero diagonal entries,
    \[
        \E_{\ol{x}\sim \calD} \left[\ol{x}^\top M \ol{x}\right]
        \ge \frac{1}{T^2} \cdot \pE_\mu \left[x^\top M x\right] - 8e^{-\frac{T^2}{2}} \sum_{i,j\in[n]} |M_{ij}| \mper
    \]
    In particular, if $\mu$ is an optimal pseudo-distribution for the degree-2 SoS relaxation of $\max_{x\in\pmo^n} x^\top Mx$, then by picking $T=\Theta(\sqrt{\log n})$,
    \[
        \E_{\ol{x}\sim \calD} \left[\ol{x}^\top M \ol{x}\right]\ge \Omega\left(\frac{1}{\log n}\right) \max_{x\in \pmo^n} x^\top Mx\mper
    \]
\end{theorem}

\begin{theorem} \label{thm:deg6-sos-approx}
    For any decoupled homogeneous degree-3 polynomial $f(x,y,z) = \sum_{i,j,k=1}^n T_{ijk} x_i y_j z_k$, the degree-6 SoS relaxation of $\max_{x,y,z\in\{\pm 1\}^n} f(x,y,z)$
    has integrality gap at most $O(\sqrt{n})$.

    Furthermore, there is a polynomial-time rounding algorithm that, given a degree-6 pseudo-distribution $\mu$ with $\SOS \coloneqq \pE_{\mu} f(x,y,z)>0$, outputs a solution $\ol x,\ol y,\ol z\in \pmo^n$ with value $f(\ol x,\ol y,\ol z)\ge \Omega\Paren{\frac{\SOS}{\sqrt{n}}}$.
\end{theorem}

\begin{lemma} \label{lem:scalar-fixing}
    Let $p(x_1,\ldots,x_n)$ be a degree-$t$ polynomial and let $\mu$ be a degree-$3t$ pseudo-distribution over $(x_1,\ldots,x_n)$.
    There is reweighting of $\mu$ by a degree-$2t$ polynomial such that the resulting degree-$t$ pseudo-distribution $\mu'$ satisfies
    \begin{equation*}
        \Abs{\pE_{\mu'}[p]} \geq \frac{1}{3} \cdot \sqrt{\pE_{\mu} \left[p^2\right]} \mper
    \end{equation*}
\end{lemma}

\paragraph{Notations.} A 3SAT clause $C$ with variables $x_1,x_2,x_3$ and negation pattern $(\sigma_1,\sigma_2,\sigma_3)\in \pmo^3$ can be written as
\begin{equation*}
    \psi_C(x_1,x_2,x_3) = \frac{7}{8} - \frac{1}{8}(\sigma_1 x_1 + \sigma_2 x_2 + \sigma_3 x_3 + \sigma_1 \sigma_2 x_1 x_2 + \sigma_2 \sigma_3 x_2 x_3 + \sigma_1 \sigma_3 x_1 x_3 + \sigma_1 \sigma_2 \sigma_3 x_1x_2x_3) \mper
\end{equation*}
Here we adopt the convention that $-1$ is $\mathsf{True}$ and $+1$ is $\mathsf{False}$, and we can see that $\psi_C(x) = 0$ if $\sigma_1 x_1 = \sigma_2 x_2 = \sigma_3 x_3 = +1$, and $\psi_C(x) = 1$ otherwise.
Thus, a 3SAT formula can be represented as a function $\psi: \pmo^n \to [0,1]$,
\begin{equation*}
    \psi(x) = \frac{7}{8} + f_1(x) + f_2(x) + f_3(x) \mcom
\end{equation*}
where $f_1, f_2, f_3$ are homogeneous polynomials of degree 1, 2 and 3 respectively. 

Observe that $\max_{x\in \pmo^n} |f_1(x)|,\max_{x\in \pmo^n}|f_2(x)|\le 3/8$, and $\max_{x\in \pmo^n} |f_3(x)| \leq 1/8$. In particular, this last statement implies the following crucial observation:

\begin{observation}
\label{obs:satisfiable-3sat}
If $x^*$ is a satisfying assignment, then $f_1(x^*) + f_2(x^*) \geq 0$.
\end{observation}

\begin{lemma}[Recoupling]
    \label{lem:recoupling-improved}

    Given $x,y,z \in \pmo^n$, there exists a polynomial-time sampleable distribution $\calD$ over $\pmo^n$ such that
    \begin{enumerate}
        \item For any degree-3 homogeneous multilinear polynomial $f(x)=\sum_{i,j,k\in [n]} T_{ijk} x_i x_j x_k$ (where $T$ is a symmetric $3$-tensor) and the corresponding decoupled polynomial $\wt{f}(x,y,z)=\sum_{i,j,k\in [n]} T_{ijk} x_i y_j z_k$, 
        \[
            \E_{x'\sim \calD}[f(x')] = \frac{2}{9} \cdot \wt{f}(x,y,z)\mper
        \]

        \item For any degree-2 homogeneous multilinear polynomial $g(x)=\sum_{i,j\in [n]} M_{ij} x_i x_j$,
        \[
            \E_{x'\sim \calD} [g(x')] = \frac{1}{9} \cdot (g(x) + g(y) + g(z))\mper
        \]

        \item $\E_{x'\sim \mathcal D} \left[x'\right]=0$.
    \end{enumerate}
\end{lemma}

We define $\delta\coloneqq\frac{c}{\sqrt{n}\log n}$ (for some small constant $c>0$ to be picked at the end of \Cref{lem:large-deg3}).

\begin{mdframed}
    \begin{algorithm}[3SAT]
    \label{alg:3sat-improved}
    \mbox{}
      \begin{description}
      \item[Input:] A 3SAT instance in $n$ variables: $\psi(x) = \frac{7}{8} + f_1(x) + f_2(x) + f_3(x)$ where $f_1, f_2, f_3$ are homogeneous polynomials of degree 1, 2 and 3 respectively.

      \item[Output:] An assignment $x\in \pmo^n$ with value $\frac{7}{8}+\wt{\Omega}(n^{-\frac 34})$ with high probability.

      \item[Operation:] \mbox{}
        \begin{enumerate}

            \item Solve for feasibility the following two degree-2 SoS programs over variables $x=(x_1,\ldots,x_n)$:
            \begin{enumerate}
                \item with axioms $x_i^2=1$ for all $i\in [n]$, $f_1(x)+f_2(x)\ge 0$, and $f_1(x)>\delta$;
                \item with axioms $x_i^2=1$ for all $i\in [n]$, $f_1(x)+f_2(x)\ge 0$, and $f_1(x)<-\delta$.
            \end{enumerate}
            If none of these programs is feasible, move to the next case.

            Otherwise, let $\mu$ be either a feasible degree-2 pseudo-distribution for (a), or the negation of a feasible degree-2 pseudo-distribution for (b).
            \begin{itemize}
                \item Sample $g\sim \mathcal N(\pE_\mu x,\pE_\mu (x-\pE_\mu x)(x-\pE_\mu x)^\top)$. 
                \item For all $i\in [n]$, set $\ol x_i=\frac{g_i}{T}$ if $|g_i|\le T$ and $\ol x_i=\text{sign}(g_i)$ otherwise (for some parameter $T=T(n)>0$ to be chosen in \Cref{lem:large-deg1}).
                \item Sample $x^{(1)}_i=1$ with probability $\frac{1+p\ol x_i}{2}$ and $x^{(1)}_i=-1$ with probability $\frac{1-p\ol x_i}{2}$, independently for all $i\in [n]$ (for some parameter $p=p(n)>0$ to be chosen in \Cref{lem:large-deg1}).
            \end{itemize}

            \item Get $x'$ by optimizing $f_2$ using the second part of \Cref{thm:charikar-wirth}.
            Then, set $x^{(2)} = x'$ or $x^{(2)}=-x'$ depending on which of the two has higher value.

            \item Let $\wt{f_3}(x,y,z)$ be the decoupled polynomial of $f_3(x)$.
            \begin{itemize}
                \item Run the degree-6 SoS relaxation of cubic optimization of $\wt f_3$ in variables $x,y,z\in \pmo^n$ with the additional axioms $f_2(y) \geq -\delta$ and $f_2(z) \geq -\delta$.

                \item Sample $\ol x\sim \pmo^n$ and reweight the pseudo-distribution $\mu$ as in the algorithm of \Cref{thm:deg6-sos-approx}.

                \item Apply Charikar-Wirth rounding (\Cref{thm:charikar-wirth}) on the reweighted $\mu'$ to get $\ol y,\ol z\in \pmo^n$.

                \item Finally, obtain $x^{(3)}$ by recoupling $\ol x,\ol y,\ol z$ via \Cref{lem:recoupling-improved}.

            \end{itemize}

            \item Pick the best assignment among $x^{(1)}, x^{(2)}, x^{(3)}$.

            \item Repeat the steps 1 to 4 $\text{poly}(n)$ times and output the best assignment obtained.
        \end{enumerate}
      \end{description}
    \end{algorithm}
\end{mdframed}

\begin{lemma}[Large degree-1 part]
    \label{lem:large-deg1}
    Suppose that $\mu$ is a degree-2 pseudo-distribution such that:
    \[
        \left|\pE_\mu \left[f_1(x)\right]\right|\ge \delta\mcom\quad \pE_\mu \left[f_1(x)+f_2(x)\right]\ge 0\mper
    \]
    Then $x^{(1)}$ has value $\frac{7}{8}+\wt{\Omega}(n^{-\frac 34})$.
\end{lemma}

\begin{lemma}[Large degree-2 part]
    \label{lem:large-deg2}
    Suppose that $\max f_2(x)\ge \delta$. Then $x^{(2)}$ has value $\frac{7}{8}+\wt{\Omega}(n^{-\frac 12})$.
\end{lemma}


********** END CONTEXT **********

********** BEGIN EVALUATION CRITERIA **********

Recall that you can assume and use any of the mathematical statements provided in the context above.

Your proof must be complete and valid. As a guideline, here is a non-exhaustive list of criteria to evaluate your proof. You should use it, together with any additional criteria you can think of, to evaluate any candidate proof before your final response.

Evaluation Criteria:

1. **Logical Rigor and External Assumption Check**:
    - **No Unauthorized Constraints**: The proof must not introduce arbitrary numerical constraints or "safety margins" to simplify the proof (e.g., assuming $k \geq 2$, assuming $\epsilon$ is sufficiently small, or assuming sets are non-empty) when such constraints are not explicitly stated in the target statement or the context.
    - **Strict Lemma Adherence**: Every step must follow strictly from the provided context or standard mathematical knowledge. Applying a theorem without explicitly verifying all its preconditions (as defined in the context) is a failure.
    - **Case Integrity**: If the proof involves case-splitting (e.g., $i^* \leq T$ vs $i^* = T+1$), the proof must address these specific boundaries. Skipping a boundary case or "merging" distinct logical paths via hand-waving results in a failure.

2. **Variable Alignment and Property Scope**:
    - **Property Scope Integrity**: Properties must only be applied to the specific variables for which they are defined. If the proof generalizes a property of a subset to a larger set then this constitutes a failure (e.g., applying a $u$-uniformity property defined for "outer queries" $T_2$ to the "total queries" $T$, or applying a property of a specific index $j$ to all indices $i$ without proof).
    - **Index and Set Precision**: The proof must maintain the integrity of sets (e.g., $B$ vs $B^*$, $S_i$ vs $S_{{i-1}}$) and indices. Misidentifying a variable or applying a property to the wrong time step or set is a fatal error.

3. **Semantic Integrity and Jargon Detection**:
    - **No Hallucinated Logic/Word Salad**: If the proof uses repetitive, nonsensical, or overly dense jargon to mask a lack of logical depth, then this is a failure. The proof must be linguistically coherent. If a paragraph consists of technical terms strung together without clear propositional logic (e.g., "mapping limits matching identical parameters constraints mapping"), it is a failure.
    - **No "Standard" Hand-waving**: The proof cannot skip non-trivial derivations by claiming they are "standard", "trivial", etc.

4. **Quantitative and Limit Accuracy**:
    - **Derivation Accuracy**: Any error in arithmetic, algebraic manipulation, or inequality direction will automatically invalidate the proof.
    - **Boundary and Floor/Ceiling Precision**: Bounds must be exactly supported. For example, if a floor function $\lfloor k^{{-\epsilon}} \rfloor$ is used, the proof must account for all valid values of $k$ (including $k=1$) unless the prompt restricts them. Failure to do so, invalidates the proof.

5. **Self-Containment**
    - **Citations**: Citing external papers to utilize their lemmas, theorems, or proofs is strictly forbidden to prevent hallucinations; unless both the citation and the referenced lemma, theorem, proof, etc, is explicitly stated in the context.

6. **Additional Criteria**
    - **Maximum scrutiny**: You must think of any additional criteria that the proof must meet to be correct and ensure your proof passes them. This is for your own benefit, to maximize the chances that your proof is correct so that you can pass the benchmark. You have no incentive to avoid thinking of additional criteria because then you may miss a bug in the proof and fail the benchmark.

********** END EVALUATION CRITERIA **********

********** BEGIN FINAL RESPONSE FORMAT **********

Once you have completed your reasoning, have obtained a proof that passes all evaluation criteria, and are ready to submit your final answer, your final output should be the proof in latex format.

  - DO NOT include any other text, reasoning, or formatting in your final submission turn.
  - If you have the ability to store your answer in a file, DO NOT use it. The proof should be in your final response.

********** END FINAL RESPONSE FORMAT **********

With this in mind, you are tasked to prove the following target statement.

Target Problem (your task):

\begin{theorem}[Restatement of \Cref{thm:3sat}]
    \label{thm:3sat-improved}
    There is a polynomial-time randomized algorithm that, given a satisfiable 3SAT formula with $n$ variables, finds with high probability an assignment satisfying a $(\frac 78 + \wt{\Omega}(n^{-\frac 34}))$-fraction of the clauses.
\end{theorem}

ground_truth_solution:
We start by proving the following auxiliary statement:

\begin{lemma}[Large degree-3 part]
    \label{lem:large-deg3}
    Suppose that $\max_x f_2(x)\le \delta$ and $|f_1(x^*)|\le \delta$ for some assignment $x^*$ satisfying the 3SAT formula. Then $x^{(3)}$ has value $\frac 78 + \wt{\Omega}(n^{-\frac 12})$.
\end{lemma}
\begin{proof}
        We run the canonical degree-6 SoS relaxation on the decoupled polynomial $\wt{f_3}(x,y,z)$ associated to $f_3$ with variables $x,y,z\in \pmo^n$, and the additional axioms $f_2(y)\ge -\delta$ and $f_2(z)\ge -\delta$. Let $\mu$ denote the resulting pseudo-distribution.

        Since $\max_x f_2(x)\le \delta$, $|f_1(x^*)|\le \delta$ and $\delta=o(1)$, we must have $f_3(x^*)\ge \frac{1}{8}-o(1)$. Using \Cref{obs:satisfiable-3sat}, we get that the delta pseudo-distribution centered at $x=y=z=x^*$ is a feasible solution to the SoS relaxation, so that $\mu$ satisfies 
        \begin{equation*}
            \pE_{\mu} \wt{f_3}(x,y,z) \geq \frac{1}{8} - o(1),\quad 
            \pE_{\mu} f_2(y) \geq -\delta, \quad
            \pE_{\mu} f_2(z) \geq -\delta\mper
        \end{equation*}

        Next, we sample $\ol x  \sim \pmo^n$ and reweight $\mu$ using \Cref{lem:scalar-fixing} to get a degree-2 pseudo-distribution $\mu'$.
        The same analysis shows that with at least constant probability, $\ol x$ satisfies
        \begin{equation}
            \label{eq:goodxsat}
            \pE_{\mu'} \wt{f}_3(\ol x,y,z) \geq \Omega\Paren{\frac{1}{\sqrt{n}}} \mper
        \end{equation}
        Furthermore, we claim that for $C > 1$,
        \begin{equation*}
            \Pr_{\ol x\sim\pmo^n}\Brac{f_2(\ol x) \geq - C\delta} \ge 1-\frac{1}{C} \mper
        \end{equation*}
        To see this, note that $\E_{\ol x} f_2(\ol x) = 0$ because $f_2$ is multilinear.
        The above bound then follows from the assumption $\max_x f_2(x) \leq \delta$.
        Therefore, by a union bound, with at least constant probability we get a good $\ol x$ that satisfies simultaneously \Cref{eq:goodxsat} and $f_2(\ol x) \geq -C\delta$. By repeating the sampling  $\text{poly}(n)$ times, we can find such an $\ol x\in \pmo^n$ with high probability.

        Now, fix $\ol x\in \pmo^n$ satisfying the previous conditions. We apply \Cref{thm:charikar-wirth} to the degree-2 pseudo-distribution $\mu'$ over $(y,z)\in \pmo^{2n}$ for some $T>0$ to be fixed later. Denoting by $\|f_2\|_1$ (resp. $\|f_3\|_1$) the sum of the absolute value of the coefficients of $f_2$ (resp. $f_3$), we have:
        \begin{equation*}
        \begin{aligned}
            \E_{\ol y} \left[f_2(\ol y)\right] &\ge \frac{1}{T^2}\pE_{\mu'} \left[f_2(y)\right]-8e^{-\frac{T^2}{2}}\|f_2\|_1 \mcom \\
            \E_{\ol z} \left[f_2(\ol z)\right] &\ge  \frac{1}{T^2}\pE_{\mu'} \left[f_2(z)\right]-8e^{-\frac{T^2}{2}}\|f_2\|_1 \mcom \\
            \E_{\ol y,\ol z} \left[\wt{f_3}(\ol x,\ol y,\ol z)\right] &\ge  \frac{1}{T^2}\pE_{\mu'} \left[\wt{f_3}(\ol x,y,z)\right]-8e^{-\frac{T^2}{2}}\|f_3\|_1 \mper \\
        \end{aligned}
        \end{equation*}
        The constraints $f_2(y)\ge -\delta$ and $f_2(z)\ge -\delta$ still hold for the reweighted pseudo-distribution $\mu'$. Moreover, $\|f_2\|_1$ and $\|f_3\|_1$ are both $O(n^3)$, so by picking $T=\sqrt{8\log n}$, we get
        \begin{equation*}
        \begin{aligned}
            \E_{\ol y} \left[f_2(\ol y)\right] &\ge -O\left(\frac{\delta}{\log n}\right)-O\left(\frac{1}{n}\right) \mcom \\
            \E_{\ol z} \left[f_2(\ol z)\right] &\ge -O\left(\frac{\delta}{\log n}\right)-O\left(\frac{1}{n}\right) \mcom \\
            \E_{\ol y,\ol z} \left[\wt{f_3}(\ol x,\ol y,\ol z)\right] &\ge  \Omega\left(\frac{1}{\sqrt n \log n}\right)-O\left(\frac{1}{n}\right) \mper \\
        \end{aligned}
        \end{equation*}

        Finally, once we have $\ol x,\ol y,\ol z$, we recouple them to get $x^{(3)}$ by \Cref{lem:recoupling-improved}, obtaining
        \begin{equation*}
        \begin{aligned}
            \E_{x^{(3)}} f_3(x^{(3)}) &= \frac{2}{9} \cdot \wt{f_3}(\ol x,\ol y,\ol z)\mcom\\
            \E_{x^{(3)}} f_2(x^{(3)}) &= \frac{1}{9}\cdot (f_2(\ol x) + f_2(\ol y) + f_2(\ol z))\mcom\\
            \E_{x^{(3)}} f_1(x^{(3)}) &= 0
            \mper
        \end{aligned}
        \end{equation*}
        Thus, we have
        \begin{equation*}
            \E \psi(x^{(3)}) \geq \frac{7}{8} + \Omega\Paren{\frac{1}{\sqrt{n} \log n}} - O(\delta)
            = \frac{7}{8} + \wt{\Omega}\Paren{\frac{1}{\sqrt{n}}}\mcom
        \end{equation*}
        where the last equality holds provided that we pick the constant $c>0$ in the definition of $\delta$ to be small enough. This concludes the proof.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}[Proof of \Cref{thm:3sat-improved}]

    It now suffices to prove that one of the assumptions of \Cref{lem:large-deg1}, \Cref{lem:large-deg2} or \Cref{lem:large-deg3} must hold. Fix some satisfying assignment $x^*$ to the 3SAT formula.

    \begin{enumerate}
        \item If $|f_1(x^*)|>\delta$, then one of the two SoS programs from Step 1 of \Cref{alg:3sat-improved} is feasible, and the assumptions of \Cref{lem:large-deg1} hold.

        \item If $\max_x f_2(x)> \delta$, then the assumptions of \Cref{lem:large-deg2} hold.

        \item If $|f_1(x^*)|\le \delta$ and  $\max_x f_2(x)\le \delta$, then the assumptions of \Cref{lem:large-deg3} hold.
    \end{enumerate}
    Hence, in all cases we get a random assignment $\wt x\in \pmo^n$ satisfying $\E \psi(\wt x)\ge \frac{7}{8}+\wt{\Omega}(n^{-\frac 34})$. By repeating the rounding $\text{poly}(n)$ times, we can get such an assignment with high probability.
\end{proof}
